"""Normalize a messy arithmetic expression to plain digits/operators, then compute it.

Bundled because the SKILL.md body asking for normalization "before computing" is a
step the agent skips: number words and thousands separators need the same handful of
substitutions every time, which is code, not judgment.

    python scripts/normalize.py '2,000 minus 1,000'   ->  1000
    python scripts/normalize.py --self-check          ->  ok
"""

import re
import sys

WORDS = {"plus": "+", "and": "+", "minus": "-", "less": "-",
         "times": "*", "multiplied by": "*"}
SAFE = set("0123456789 +-*")


def normalize(expr):
    s = str(expr).lower()
    s = re.sub(r"(\d),(\d\d\d)", r"\1\2", s)          # 1,200 -> 1200
    for word, op in WORDS.items():
        s = re.sub(rf"\b{re.escape(word)}\b", op, s)
    return re.sub(r"\s+", " ", s).strip()


def compute(expr):
    s = normalize(expr)
    if not set(s) <= SAFE:
        raise ValueError(f"cannot normalize {expr!r} -> {s!r}")
    return str(int(eval(s, {"__builtins__": {}}, {})))


def _self_check():
    for raw, want in (("2 + 3", "5"), ("3 plus 4", "7"), ("8 times 3", "24"),
                      ("1,200 + 5", "1205"), ("2,000 minus 1,000", "1000")):
        got = compute(raw)
        assert got == want, f"{raw!r}: expected {want}, got {got}"
    print("ok")


if __name__ == "__main__":
    if "--self-check" in sys.argv:
        _self_check()
    else:
        print(compute(sys.argv[1]))
